args.command:
cd /workspace && cat > next.config.ts <<'EOF'
import type { NextConfig } from 'next'

const nextConfig: NextConfig = {
  cacheComponents: true,
}

export default nextConfig
EOF
cat > lib/projects.ts <<'EOF'
import { cacheLife, cacheTag } from 'next/cache'

// Shared across all members: safe to cache and include in the static shell.
export async function getProjectTotals() {
  'use cache'
  cacheLife('hours')
  cacheTag('project-totals')

  await new Promise((resolve) => setTimeout(resolve, 120))
  return { active: 12, archived: 4 }
}
EOF
cat > app/page.tsx <<'EOF'
import { Suspense } from 'react'
import { cookies, headers } from 'next/headers'
import { getProjectTotals } from '@/lib/projects'

export default function DashboardPage() {
  return (
    <main>
      <h1>Workspace</h1>
      <Suspense fallback={<MemberDetailsFallback />}>
        <MemberDetails />
      </Suspense>
      <ProjectTotals />
    </main>
  )
}

// Request-specific: reads cookies and headers, so it streams at request time.
async function MemberDetails() {
  const cookieStore = await cookies()
  const requestHeaders = await headers()
  const member = cookieStore.get('member')?.value ?? 'Guest'
  const team = cookieStore.get('team')?.value ?? 'Community'
  const region = requestHeaders.get('x-region') ?? 'global'

  return (
    <>
      <p>Welcome, {member}</p>
      <p>Team: {team}</p>
      <p>Region: {region}</p>
    </>
  )
}

function MemberDetailsFallback() {
  return (
    <>
      <p>Welcome, …</p>
      <p>Team: …</p>
      <p>Region: …</p>
    </>
  )
}

// Shared: cached data, prerendered into the static shell.
async function ProjectTotals() {
  const totals = await getProjectTotals()
  return <p>{totals.active} active projects</p>
}
EOF
npm run build 2>&1 | tail -30

